'use strict';
const C=window.CONTENT,Q=C.questions,M=C.modules,byId=Object.assign(Object.create(null),Object.fromEntries(Q.map(q=>[q.id,q])));
const KEY='evergreen-drive-v1';
const fresh=()=>({version:1,lessons:[],stats:{},bookmarks:[],history:[],activity:{},xp:0,sound:false,motion:false,session:null});
let S=fresh(),storageOK=true,flash=null,toastTimer,audioCtx;
try{const raw=localStorage.getItem(KEY);if(raw)S=validateState(JSON.parse(raw));}catch(e){storageOK=false;}
function validateState(x){
 if(!x||x.version!==1||!Array.isArray(x.lessons)||!Array.isArray(x.history)||!x.stats||typeof x.stats!=='object'||Array.isArray(x.stats))throw Error('Invalid backup');
 const n=fresh(),num=(v,max=1e8)=>Number.isFinite(v)&&v>=0&&v<=max;
 n.lessons=[...new Set(x.lessons.filter(k=>byId[k]))];n.bookmarks=[...new Set((Array.isArray(x.bookmarks)?x.bookmarks:[]).filter(k=>byId[k]))];
 for(const [id,v]of Object.entries(x.stats)){if(byId[id]&&v&&num(v.seen)&&num(v.correct)&&v.correct<=v.seen&&num(v.run)&&num(v.due,1e15))n.stats[id]={seen:v.seen,correct:v.correct,run:v.run,due:v.due,lastCorrect:!!v.lastCorrect};}
 n.history=x.history.filter(h=>h&&typeof h.title==='string'&&h.title.length<150&&num(h.score,40)&&num(h.total,Q.length)&&h.score<=h.total&&num(h.date,1e15)).slice(-200).map(h=>({title:h.title,score:h.score,total:h.total,date:h.date,mock:!!h.mock,testId:Number.isInteger(h.testId)?h.testId:null}));
 n.xp=num(x.xp)?x.xp:0;n.sound=!!x.sound;n.motion=!!x.motion;
 if(x.activity&&typeof x.activity==='object')for(const[k,v]of Object.entries(x.activity))if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&num(v))n.activity[k]=v;
 const a=x.session;
 if(a&&Array.isArray(a.ids)&&a.ids.length<=Q.length&&new Set(a.ids).size===a.ids.length&&a.ids.every(id=>byId[id])&&['mock','practice'].includes(a.mode)&&Number.isInteger(a.index)&&a.index>=0&&a.index<a.ids.length&&a.orders&&a.ids.every(id=>Array.isArray(a.orders[id])&&a.orders[id].length===4&&[...a.orders[id]].sort().join()==='0,1,2,3')&&a.answers&&Object.entries(a.answers).every(([id,v])=>a.ids.includes(id)&&Number.isInteger(v)&&v>=0&&v<4)&&num(a.started,1e15)&&num(a.elapsed||0,1e15)&&Array.isArray(a.recorded)&&a.recorded.every(id=>a.ids.includes(id))&&Array.isArray(a.flags)&&(!a.finished||num(a.score,a.ids.length)))n.session={ids:a.ids,orders:a.orders,answers:a.answers,index:a.index,mode:a.mode,title:String(a.title).slice(0,150),flags:a.flags.filter(id=>a.ids.includes(id)),started:a.started,elapsed:a.elapsed||0,finished:!!a.finished,recorded:[...new Set(a.recorded)],score:a.score,testId:Number.isInteger(a.testId)&&a.testId>=1&&a.testId<=20?a.testId:null};
 return n;
}
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));storageOK=true;}catch(e){storageOK=false;toast('Progress cannot be saved in this browser. Export a backup in Preferences.');}chrome();}
function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function activity(xp=0){const d=dateKey();S.activity[d]=(S.activity[d]||0)+1;S.xp+=xp;}
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function shuffle(a,rng=Math.random){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function seeded(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function mockIds(n){const ids=[];M.forEach((m,i)=>{const pool=Q.filter(q=>q.module===m.id);const take=(items,count,salt)=>{const ordered=shuffle(items,seeded(84629+i*9173+salt));return Array.from({length:count},(_,k)=>ordered[((n-1)*count+k)%ordered.length]);};if(m.id==='signals'||m.id==='lanes'){ids.push(...take(pool.filter(q=>q.visualQuestion),m.id==='signals'?4:2,1).concat(take(pool.filter(q=>!q.visualQuestion),2,2)).map(q=>q.id));}else ids.push(...take(pool,3,0).map(q=>q.id));});return shuffle(ids,seeded(84629+n*9173));}
function source(q){return `<a class="source-link" href="assets/washington-driver-guide.pdf#page=${q.page}" target="_blank" rel="noopener">Driver Guide §${esc(q.section)} · PDF page ${q.page} ↗</a>`;}
function mod(id){return M.find(m=>m.id===id);}
function completed(m){return Q.filter(q=>q.module===m.id&&S.lessons.includes(q.id)).length;}
function total(m){return Q.filter(q=>q.module===m.id).length;}
function wrongIds(){return Q.filter(q=>S.stats[q.id]&&!S.stats[q.id].lastCorrect).map(q=>q.id);}
function dueIds(){return Q.filter(q=>S.stats[q.id]&&S.stats[q.id].due<=Date.now()).map(q=>q.id);}
function mastered(){return Q.filter(q=>(S.stats[q.id]?.run||0)>=2).length;}
function streak(){let count=0,d=new Date();if(!S.activity[dateKey(d)])d.setDate(d.getDate()-1);while(S.activity[dateKey(d)]){count++;d.setDate(d.getDate()-1);}return count;}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function sound(kind='tap'){if(!S.sound)return;try{audioCtx ||=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const seq=kind==='correct'?[523,659,784]:kind==='finish'?[523,659,784,1047]:kind==='wrong'?[294,262]:[440];seq.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+i*.09;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.075,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+.18);o.connect(g);g.connect(audioCtx.destination);o.start(t);o.stop(t+.2);});}catch(e){}}
const navs=[['home','⌂','Dashboard'],['course','▤','Study routes'],['practice','✦','Practice'],['mock','▣','Mock tests'],['review','↺','Review'],['progress','◴','Progress'],['signs','⬡','Visual signs'],['source','▧','The guide']];
function chrome(){const route=location.hash.slice(1).split('/')[0]||'home';document.getElementById('nav').innerHTML=navs.map(([id,icon,label])=>`<a class="nav-item ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''} title="${label}"><span class="nav-icon" aria-hidden="true">${icon}</span><span class="nav-name">${label}</span>${id==='review'&&wrongIds().length?`<span class="nav-count">${wrongIds().length}</span>`:''}</a>`).join('');document.getElementById('xp-label').textContent=S.xp+' XP';const b=document.getElementById('sound');b.textContent=S.sound?'♫':'♪';b.setAttribute('aria-label',S.sound?'Turn sound off':'Turn sound on');b.setAttribute('aria-pressed',String(S.sound));document.body.classList.toggle('reduced-motion',S.motion);}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
function heading(eyebrow,title,desc,tag=''){return `<div class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`;}
function scenic(){return `<svg class="hero-art" viewBox="0 0 520 320" preserveAspectRatio="xMidYMax slice" aria-hidden="true"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#e1edda"/><stop offset="1" stop-color="#cadfca"/></linearGradient></defs><path fill="url(#sky)" d="M0 0h520v320H0z"/><circle cx="390" cy="70" r="35" fill="#fbefb2"/><path d="M0 208 142 63 272 219 366 121 520 240V320H0" fill="#aec7af"/><path d="m99 108 43-45 50 61-29-12-20 6-13-19Z" fill="#f6f7e8"/><path d="M0 232Q110 167 228 218T520 201V320H0" fill="#8eae8f"/><path d="M0 283Q133 227 259 261T520 242V320H0" fill="#698d70"/><path d="M306 189C285 221 398 229 326 268S288 302 293 330" fill="none" stroke="#e8e8d1" stroke-width="47"/><path d="M306 189C285 221 398 229 326 268S288 302 293 330" fill="none" stroke="#82958b" stroke-width="35"/><path d="M306 189C285 221 398 229 326 268S288 302 293 330" fill="none" stroke="#f5e9b7" stroke-width="2" stroke-dasharray="9 10"/><g fill="#35624e"><path d="m409 157-25 49h50Zm0 25-34 58h68Z"/><path d="m453 204-20 37h40Zm0 19-28 47h56Z"/><path d="m192 187-19 35h38Zm0 18-26 44h52Z"/><path d="m490 135-21 42h42Zm0 21-31 52h62Z"/></g><g fill="#4f6b4c"><path d="M405 229h8v32h-8zM450 261h6v24h-6zM189 239h6v21h-6zM486 199h8v26h-8z"/></g><g transform="translate(325 253) rotate(22)"><rect x="-13" y="-23" width="26" height="44" rx="8" fill="#f5ca70"/><rect x="-9" y="-13" width="18" height="13" rx="3" fill="#42645b"/><rect x="-8" y="8" width="16" height="7" rx="2" fill="#698675"/><rect x="-16" y="-14" width="4" height="9" rx="2" fill="#254d40"/><rect x="12" y="-14" width="4" height="9" rx="2" fill="#254d40"/></g><g transform="translate(425 99)"><rect width="57" height="33" rx="4" fill="#35604e" stroke="#f2f3db" stroke-width="2"/><text x="28" y="14" text-anchor="middle" fill="#fff9da" font-size="8" font-family="sans-serif">WASHINGTON</text><text x="28" y="26" text-anchor="middle" fill="#fff9da" font-size="10" font-family="sans-serif">adventure ↑</text><path d="M28 33v25" stroke="#6b8067" stroke-width="4"/></g></svg>`;}
function stat(icon,color,value,label){return `<div class="stat"><div class="stat-icon ${color}" aria-hidden="true">${icon}</div><div><strong>${value}</strong><span class="label">${label}</span></div></div>`;}
function routeRow(m){const n=completed(m),t=total(m);return `<button class="route-row" data-go="course/${m.id}"><span class="route-symbol ${m.color}" aria-hidden="true">${m.icon}</span><span class="route-info"><strong>${m.title}</strong><span>${m.subtitle}</span><span class="progress-track"><span style="width:${n/t*100}%"></span></span></span><span class="route-end">${n===t?'✓':n+'/'+t} →</span></button>`;}
function home(){const next=M.find(m=>completed(m)<total(m))||M[0],seen=Object.keys(S.stats).length,passed=S.history.filter(h=>h.mock&&h.score>=32).length;return heading('A little practice. A lot of possibility.','Your next adventure starts here.','Let’s make the road ahead feel a little more familiar.','● 100% offline ready')+`<section class="hero"><div class="hero-copy"><div class="eyebrow">LEARN AT YOUR PACE · DRIVE WITH CONFIDENCE</div><h2>Small steps today.<br>Open roads tomorrow.</h2><p>Explore Washington’s rules of the road, build your confidence, and enjoy the journey to test day.</p><button class="btn" data-go="course/${next.id}">${S.lessons.length?'Continue your journey':'Start your journey'} <span>↗</span></button></div>${scenic()}</section><div class="stats">${stat('▤','mint',Math.round(S.lessons.length/Q.length*100)+'%','STUDY ROUTES COMPLETE')}${stat('✦','lavender',seen+'/'+Q.length,'QUESTIONS EXPLORED')}${stat('⚑','peach',passed,'MOCK TESTS PASSED')}${stat('☀','yellow',streak()+' day'+(streak()===1?'':'s'),'YOUR STUDY STREAK')}</div>${S.session?`<div class="callout">You have a saved ${S.session.mode==='mock'?'mock test':'practice session'}. <button class="text-button" data-go="session">Pick up where you left off →</button></div>`:''}${!storageOK?'<div class="callout">Browser storage is unavailable. Use Preferences → Export backup to keep your progress.</div>':''}<div class="dashboard-grid"><section><div class="section-heading"><div><h2>Your learning road trip</h2><p>Twelve routes. One more confident you.</p></div><button class="text-button" data-go="course">View all →</button></div><div class="route-list">${M.slice(M.indexOf(next),M.indexOf(next)+3).map(routeRow).join('')}</div></section><section class="card daily-card"><div class="eyebrow">YOUR DAILY DETOUR</div><div class="daily-art" aria-hidden="true">☀</div><h3>Five questions.<br>A fresh perspective.</h3><p>A tiny daily challenge to keep your knowledge moving.</p><button class="btn secondary" data-action="daily">Take the daily 5 <span>→</span></button><div class="mini-note">No timer. Just you, a few questions, and a little progress.</div></section></div><div class="section-heading"><h2>Choose your next turn</h2><span class="small muted">A little variety goes a long way.</span></div><div class="quick-grid"><button class="quick" data-go="mock"><span class="q-icon">▣</span><strong>Try the real-size challenge ↗</strong><p>20 mock tests · 40 questions each</p></button><button class="quick" data-go="signs"><span class="q-icon">⬡</span><strong>Learn the signs by sight ↗</strong><p>Illustrated cards, lane diagrams & visual practice</p></button><button class="quick" data-go="review"><span class="q-icon">↺</span><strong>Give tricky topics another go ↗</strong><p>A personal review queue that grows with you</p></button></div>`;}
function course(id){if(!id)return heading('THE SCENIC ROUTE TO KNOWING','A little wiser at every stop.','Bite-sized lessons, backed by the guide. Choose any route to begin.','12 study routes')+`<div class="grid">${M.map((m,i)=>`<section class="card module-card"><span class="module-num">ROUTE ${String(i+1).padStart(2,'0')}</span><span class="route-symbol ${m.color}">${m.icon}</span><h3>${m.title}</h3><p>${m.intro}</p><div class="small muted">${completed(m)} / ${total(m)} lessons read · §${m.section}</div><div class="progress-track"><span style="width:${completed(m)/total(m)*100}%"></span></div><button class="btn secondary" data-go="course/${m.id}">${completed(m)?'Continue route':'Explore route'} →</button></section>`).join('')}</div>`;
 const m=mod(id);if(!m)return empty('Route not found','Choose a route from the course.','course');const list=Q.filter(q=>q.module===id),idx=Math.max(0,Math.min(list.length-1,location.hash.split('/')[2]===undefined?Math.max(0,list.findIndex(q=>!S.lessons.includes(q.id))):(Number(location.hash.split('/')[2])||0))),q=list[idx];return heading(`ROUTE ${String(M.indexOf(m)+1).padStart(2,'0')} · ${m.subtitle}`,m.title,m.intro)+`<div class="study-layout"><aside class="study-tabs" aria-label="Lessons">${list.map((v,i)=>`<button class="${i===idx?'selected':''}" data-go="course/${id}/${i}" ${i===idx?'aria-current="step"':''}>${S.lessons.includes(v.id)?'✓':String(i+1).padStart(2,'0')} · ${esc(v.visual?v.choices[v.answer]:v.prompt)}</button>`).join('')}</aside><section class="card lesson-card"><div class="eyebrow">LESSON ${idx+1} OF ${list.length}</div><span class="route-symbol ${m.color}">${m.icon}</span><h2>${esc(q.prompt)}</h2>${scene(q)}<div class="lesson-fact">${esc(q.explanation)}</div>${source(q)}<p class="small" style="margin-top:18px">This is a focused study summary. Read the linked guide page for the complete context and illustrations.</p><div class="actions between"><button class="btn secondary" data-action="bookmark" data-id="${q.id}">${S.bookmarks.includes(q.id)?'★ Saved':'☆ Save for later'}</button><button class="btn" data-action="read" data-id="${q.id}" data-next="${idx+1<list.length?`course/${id}/${idx+1}`:'course'}">${idx+1<list.length?'Got it. Next lesson':'Complete this route'} →</button></div><div class="callout">Ready to retrieve it from memory? <button class="text-button" data-action="practice-topic" data-id="${id}">Practice this route →</button></div><a class="source-link" href="assets/washington-driver-guide.pdf#page=${m.start}" target="_blank" rel="noopener">Read this route in the full guide ↗</a></section></div>`;}
function empty(title,desc,dest='practice'){return `<div class="card empty"><span class="big-icon">✦</span><h2>${title}</h2><p>${desc}</p><button class="btn" data-go="${dest}">Let’s keep exploring →</button></div>`;}
function practice(){return heading('MAKE A LITTLE ROOM FOR PRACTICE','Find your flow.','Explore, make mistakes, and learn why an answer works.')+`<section class="card visual-entry"><div><div class="eyebrow">SEE IT. RECOGNIZE IT. REMEMBER IT.</div><h2>Learn the signs by sight.</h2><p>Original guide illustrations, visual flashcards, and road-marking questions.</p></div><div class="actions"><button class="btn" data-action="visual-practice">Start visual practice →</button><button class="btn secondary" data-go="signs">Explore illustrated cards</button></div></section><div class="grid"><section class="card module-card"><span class="route-symbol mint">✦</span><h3>Your own practice mix</h3><p>Choose a topic and session length. Get an explanation after every answer.</p><div class="toolbar"><label>Topic <select id="practice-topic"><option value="all">All routes</option>${M.map(m=>`<option value="${m.id}">${m.title}</option>`).join('')}</select></label><label>Questions <select id="practice-count"><option>10</option><option>20</option><option>40</option><option value="${Q.length}">All available</option></select></label></div><button class="btn" data-action="practice-custom">Start practice →</button></section><section class="card module-card"><span class="route-symbol lavender">▱</span><h3>Flashcard lane</h3><p>Think of the answer, flip the card, then tell us how it went. Cards you miss return sooner.</p><div class="small muted">${dueIds().length} cards due for another look</div><button class="btn secondary" data-action="flash">Flip some cards →</button></section><section class="card module-card"><span class="route-symbol yellow">☀</span><h3>The daily five</h3><p>Five fresh questions each day. A small, repeatable habit for the road ahead.</p><div class="small muted">Same daily set on this date · no countdown</div><button class="btn secondary" data-action="daily">Take today's challenge →</button></section><section class="card module-card"><span class="route-symbol peach">⬡</span><h3>Signs & signals sprint</h3><p>Read the colors, signals, and messages that keep the road moving.</p><button class="btn secondary" data-action="practice-topic" data-id="signals">Read the road →</button><button class="text-button" style="margin-top:14px" data-go="signs">Explore the illustrated sign atlas ↗</button></section><section class="card module-card"><span class="route-symbol pink">↗</span><h3>Right-of-way lab</h3><p>Practice the decisions behind turns, intersections, and roundabouts.</p><button class="btn secondary" data-action="practice-topic" data-id="junctions">Take your turn →</button></section><section class="card module-card"><span class="route-symbol mint">↺</span><h3>Your personal pit stop</h3><p>Return to missed questions, saved ideas, and cards ready for review.</p><button class="btn secondary" data-go="review">Visit review →</button></section></div>`;}
function mock(){return heading('A DRESS REHEARSAL FOR TEST DAY','Meet your next milestone.','20 distinct test forms. A fresh mix of topics on every route.','40 questions · 32 to pass')+`<div class="callout"><strong>The verified format:</strong> 40 multiple-choice questions; 32 correct answers (80%) to pass. These are original guide-based practice questions, not actual DOL exam items. Forms share questions from our ${Q.length}-question bank. Topic balance, the minimum of 6 visual questions per form, answer review, and the elapsed-time display are app features, not claims about the official exam interface. No official time limit is asserted. <a href="https://dol.wa.gov/driver-licenses-and-permits/driver-training-and-testing/do-i-need-take-test" target="_blank" rel="noopener">Official DOL format ↗</a></div>${S.session?.mode==='mock'?`<div class="card"><strong>${esc(S.session.title)} is in progress.</strong><div class="actions"><button class="btn" data-go="session">Resume saved test →</button></div></div>`:''}<div class="grid">${Array.from({length:20},(_,i)=>{const n=i+1,h=S.history.filter(h=>h.mock&&h.testId===n),best=h.length?Math.max(...h.map(v=>v.score)):null;return `<section class="card module-card"><span class="module-num">${h.length?best>=32?'PASSED':'KEEP PRACTICING':'NEW ADVENTURE'}</span><span class="route-symbol ${['mint','lavender','peach','yellow'][i%4]}">${String(n).padStart(2,'0')}</span><h3>Mock test ${String(n).padStart(2,'0')}</h3><p>40 questions across all 12 routes.<br>At least 6 visual questions per test.</p><div class="small muted">${h.length?`Best: ${best}/40 · ${h.length} attempt${h.length===1?'':'s'}`:'No attempts yet · take your time'}</div><button class="btn ${h.length?'secondary':''}" data-action="start-mock" data-id="${n}">${h.length?'Take it again':'Start this test'} →</button></section>`;}).join('')}</div>`;}
function modal(html){document.getElementById('modal-content').innerHTML=html;document.getElementById('modal').showModal();}
function closeModal(){document.getElementById('modal').close();}
let pendingStart=null;
function startSession(ids,title,mode='practice',testId=null){if(!ids.length){toast('No questions in this set yet. Try another route.');return;}const create=()=>{S.session={ids,orders:Object.fromEntries(ids.map(id=>[id,shuffle([0,1,2,3])])),answers:{},flags:[],index:0,mode,title,testId,started:Date.now(),elapsed:0,finished:false,recorded:[]};save();go('session');};if(S.session&&!S.session.finished){pendingStart=create;modal(`<h2>You have a session in progress.</h2><p>Resume ${esc(S.session.title)}, or replace it with this new session. Completed practice answers are already saved; an unfinished mock test is not scored.</p><div class="actions"><button class="btn" data-action="resume-modal">Resume</button><button class="btn secondary" data-action="replace-session">Start new session</button><button class="text-button" data-action="close">Cancel</button></div>`);}else create();}
function record(id,ok){const v=S.stats[id]||{seen:0,correct:0,run:0,due:0};v.seen++;v.correct+=ok?1:0;v.run=ok?v.run+1:0;v.lastCorrect=ok;const days=ok?[1,3,7,14,30][Math.min(v.run-1,4)]:0;v.due=Date.now()+(ok?days*864e5:600e3);S.stats[id]=v;activity(ok?10:2);}
function scene(q){if(q.visual&&C.visuals[q.visual]){const v=C.visuals[q.visual];return `<figure class="question-visual ${v.kind}"><img src="${v.src}" alt="${esc(v.alt)}" width="${v.kind==='diagram'?440:190}"><figcaption>Original Driver Guide illustration · PDF page ${v.page}</figcaption></figure>`;}if(q.section==='4.13'&&q.prompt.includes('same time'))return `<div class="scene"><svg viewBox="0 0 440 180" role="img" aria-label="Four-way intersection, you approach from the bottom and another vehicle approaches from your right. Both arrive together."><rect width="440" height="180" fill="#e4edde"/><path d="M180 0h80v180h-80zM0 50h440v80H0z" fill="#91a19a"/><path d="M220 0v45m0 90v45M0 90h175m90 0h175" stroke="#f6efc6" stroke-width="2" stroke-dasharray="10 8"/><rect x="231" y="138" width="19" height="33" rx="5" fill="#f7d172"/><rect x="294" y="61" width="33" height="19" rx="5" fill="#d47761"/><text x="278" y="162" font-family="sans-serif" font-size="12" fill="#254539">YOU ↑</text><text x="340" y="75" font-family="sans-serif" font-size="12" fill="#254539">← OTHER</text><text x="12" y="25" font-family="sans-serif" font-size="10" fill="#42604c">SCHEMATIC · NOT TO SCALE</text></svg></div>`;if(q.prompt.includes('STOP sign'))return '<div class="sign-face stop-sign" aria-label="Stop sign">STOP</div>';if(q.prompt.startsWith('Orange road signs'))return '<div class="sign-face" aria-hidden="true" style="background:#ed9e52;transform:rotate(45deg);border-radius:5px"><span style="transform:rotate(-45deg)">!</span></div>';return '';}
function session(){const a=S.session;if(!a)return empty('Your next session is waiting.','Pick a practice mix or a full mock test.');if(a.finished)return results();const q=byId[a.ids[a.index]],answered=a.answers[q.id]!==undefined,reveal=a.mode==='practice'&&answered,ok=a.answers[q.id]===q.answer;return `<div class="quiz-shell"><div class="quiz-top"><div><div class="eyebrow">${esc(a.title)}</div><span class="tag">Question ${a.index+1} of ${a.ids.length}</span></div><div class="question-tools"><span class="small muted" id="elapsed">${elapsed(a)}</span><button class="text-button" data-go="${a.mode==='mock'?'mock':'practice'}">Save & leave</button></div></div><div class="progress-track"><span style="width:${Object.keys(a.answers).length/a.ids.length*100}%"></span></div><section class="card quiz-card"><div class="quiz-top"><span class="eyebrow">${esc(mod(q.module).title)}</span><button class="text-button" data-action="flag">${a.flags.includes(q.id)?'⚑ Flagged':'⚐ Flag for review'}</button></div>${scene(q)}<h2 id="question-prompt">${esc(q.prompt)}</h2><div class="answers" role="group" aria-labelledby="question-prompt">${a.orders[q.id].map((choice,i)=>`<button class="answer ${a.answers[q.id]===choice?'chosen':''} ${reveal&&choice===q.answer?'correct':''} ${reveal&&a.answers[q.id]===choice&&!ok?'wrong':''}" data-action="answer" data-choice="${choice}" ${reveal?'disabled':''} aria-pressed="${a.answers[q.id]===choice}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(q.choices[choice])}${reveal&&choice===q.answer?' ✓':''}</span></button>`).join('')}</div>${reveal?`<div class="feedback ${ok?'':'incorrect'}" role="status"><strong>${ok?'Nice work. Keep that knowledge rolling.':'A useful detour. Here’s what to remember.'}</strong><p>${esc(q.explanation)}</p>${source(q)}<div style="margin-top:10px"><button class="text-button" data-action="bookmark" data-id="${q.id}">${S.bookmarks.includes(q.id)?'★ Saved':'☆ Save this question'}</button></div></div>`:''}<div class="actions between"><button class="btn secondary" data-action="previous" ${a.index===0?'disabled':''}>← Back</button>${a.index<a.ids.length-1?`<button class="btn" data-action="next" ${a.mode==='practice'&&!answered?'disabled':''}>${!answered&&a.mode==='mock'?'Skip for now':'Next question'} →</button>`:`<button class="btn" data-action="submit" ${a.mode==='practice'&&!answered?'disabled':''}>${a.mode==='mock'?'Review & submit':'Finish practice'} →</button>`}</div></section>${a.mode==='mock'?`<div class="section-heading"><span class="small muted">${Object.keys(a.answers).length}/40 answered · ${a.flags.length} flagged</span><button class="text-button" data-action="submit">Review & submit →</button></div><div class="navigator" aria-label="Question navigation">${a.ids.map((id,i)=>`<button class="${a.answers[id]!==undefined?'answered':''} ${a.flags.includes(id)?'flagged':''} ${a.index===i?'current':''}" data-action="jump" data-index="${i}" aria-label="Question ${i+1}${a.answers[id]!==undefined?', answered':', unanswered'}${a.flags.includes(id)?', flagged':''}">${i+1}</button>`).join('')}</div><p class="small muted">Green = answered · gold underline = flagged. You can change answers until submission.</p>`:'<p class="small muted">Keyboard: 1–4 to choose an answer. Enter to continue after answering.</p>'}</div>`;}
function elapsed(a){const s=Math.floor((Date.now()-a.started)/1000);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')} elapsed`;}
function submit(){const a=S.session;if(!a||a.finished)return;if(a.mode==='mock'){const left=a.ids.filter(id=>a.answers[id]===undefined).length;modal(`<h2>Ready to see how you did?</h2><p>${left?`${left} unanswered question${left===1?'':'s'} will be counted as incorrect.`:'All 40 questions have an answer.'} ${a.flags.length?`${a.flags.length} question${a.flags.length===1?' is':'s are'} flagged for review.`:''}</p><p>Your answers will be locked after submission.</p><div class="actions"><button class="btn" data-action="finish">Submit test</button><button class="btn secondary" data-action="close">Keep reviewing</button></div>`);}else finish();}
function finish(){const a=S.session;if(!a||a.finished)return;closeModal();let score=0;a.ids.forEach(id=>{const ok=a.answers[id]===byId[id].answer;if(ok)score++;if(!a.recorded.includes(id)){record(id,ok);a.recorded.push(id);}});a.finished=true;a.score=score;S.history.push({title:a.title,score,total:a.ids.length,date:Date.now(),mock:a.mode==='mock',testId:a.testId});S.history=S.history.slice(-200);activity(a.mode==='mock'&&score>=32?50:10);save();sound('finish');render();}
function results(){const a=S.session,pct=Math.round(a.score/a.ids.length*100),pass=a.mode==='mock'&&a.score>=32;return `<div class="quiz-shell"><section class="card result-summary"><div class="eyebrow">${esc(a.title)} · COMPLETE</div><div class="score-ring ${!S.motion?'celebrate':''}" style="--pct:${pct}%"><strong>${a.score}/${a.ids.length}</strong><span>${pct}% correct</span></div><h1>${a.mode==='mock'?(pass?'A milestone worth celebrating.':'Every detour teaches you something.'):'One step further down the road.'}</h1><p>${a.mode==='mock'?(pass?'You reached the practice passing score of 32/40.':'The practice passing score is 32/40. Take a look at your tricky topics and try again.'):'Your progress is saved. Take a moment to understand the questions below.'}</p><p class="small">Practice performance is a learning signal, not a guarantee of an official test result.</p><div class="actions" style="justify-content:center"><button class="btn" data-action="retry-missed">Practice missed questions →</button><button class="btn secondary" data-go="${a.mode==='mock'?'mock':'practice'}">${a.mode==='mock'?'Choose another test':'Explore more practice'}</button></div></section><div class="section-heading"><h2>Your answer review</h2><label class="small"><input type="checkbox" id="missed-only"> Missed only</label></div><div id="result-list">${resultItems(false)}</div></div>`;}
function resultItems(missed){const a=S.session;const items=a.ids.filter(id=>!missed||a.answers[id]!==byId[id].answer);if(!items.length)return empty('A clean sweep.','No missed answers in this session.','mock');return `<section class="card">${items.map(id=>{const q=byId[id],ok=a.answers[id]===q.answer;return `<article class="review-item"><div class="eyebrow">${ok?'✓ CORRECT':'↺ ANOTHER LOOK'} · QUESTION ${a.ids.indexOf(id)+1}</div><h3>${esc(q.prompt)}</h3>${scene(q)}<p class="${ok?'good':'bad'}">Your answer: ${a.answers[id]===undefined?'Unanswered':esc(q.choices[a.answers[id]])}</p>${!ok?`<p class="good">Correct answer: ${esc(q.choices[q.answer])}</p>`:''}<p>${esc(q.explanation)}</p>${source(q)} <button class="text-button" data-action="bookmark" data-id="${id}">${S.bookmarks.includes(id)?'★ Saved':'☆ Save'}</button></article>`;}).join('')}</section>`;}
function review(){const wrong=wrongIds(),due=dueIds();return heading('YOUR PERSONAL PIT STOP','A second look goes a long way.','Mistakes are useful. Turn them into something you remember.')+`<div class="stats">${stat('↺','peach',wrong.length,'MISSED LAST TIME')}${stat('◷','yellow',due.length,'DUE FOR RECALL')}${stat('★','lavender',S.bookmarks.length,'SAVED QUESTIONS')}${stat('✓','mint',mastered(),'TWO CORRECT IN A ROW')}</div><div class="actions"><button class="btn" data-action="review-wrong" ${wrong.length?'':'disabled'}>Practice missed questions →</button><button class="btn secondary" data-action="flash-due" ${due.length?'':'disabled'}>Review due cards</button><button class="btn secondary" data-action="review-saved" ${S.bookmarks.length?'':'disabled'}>Practice saved questions</button></div><div class="callout">A correct answer schedules recall in 1, 3, 7, 14, then 30 days as your correct streak grows. A missed answer returns in 10 minutes. These are app learning rules, not DOL requirements.</div><div class="section-heading"><h2>${wrong.length?'Your next learning opportunities':'A clear road ahead'}</h2></div>${wrong.length?`<div class="route-list">${wrong.map(id=>{const q=byId[id];return `<article class="card"><h3>${esc(q.prompt)}</h3>${scene(q)}<p class="small">${esc(q.explanation)}</p>${source(q)}<div class="actions"><button class="text-button" data-go="course/${q.module}/${Q.filter(v=>v.module===q.module).findIndex(v=>v.id===id)}">Revisit lesson →</button></div></article>`;}).join('')}</div>`:empty('Nothing missed is waiting.','Start a practice session and we’ll collect questions that deserve another look.')}`;}
function startFlash(ids){ids=ids||[...dueIds(),...shuffle(Q.filter(q=>!dueIds().includes(q.id)).map(q=>q.id))];if(!ids.length){toast('No cards are due yet.');return;}flash={ids:ids.slice(0,20),index:0,revealed:false,known:0};go('flash');}
function flashView(){if(!flash)return empty('Ready for a little recall?','Start a deck from Practice.');if(flash.index>=flash.ids.length)return empty('That’s a wrap for this deck.',`${flash.known} of ${flash.ids.length} cards marked remembered. Your recall schedule is updated. Keep practicing with multiple-choice questions to check your confidence.`);const q=byId[flash.ids[flash.index]];return `<div class="quiz-shell">${heading('FLASHCARD LANE','Think. Flip. Remember.','Try to answer in your own words before you turn the card.')}<div class="quiz-top"><span class="tag">Card ${flash.index+1} of ${flash.ids.length}</span><span class="small muted">${esc(mod(q.module).title)}</span></div>${scene(q)}<button class="flashcard ${flash.revealed?'flipped':''}" data-action="flip"><span class="eyebrow">${flash.revealed?'THE TAKEAWAY':'WHAT DO YOU REMEMBER?'}</span><h2>${esc(flash.revealed?q.choices[q.answer]:q.prompt)}</h2>${flash.revealed?`<p>${esc(q.explanation)}</p>`:'<span class="small">Click to reveal · or press Space</span>'}</button>${flash.revealed?`<div class="actions between"><button class="btn secondary" data-action="flash-rate" data-known="no">Still learning ↺</button>${source(q)}<button class="btn" data-action="flash-rate" data-known="yes">Remembered it ✓</button></div>`:''}<p class="small muted" style="margin-top:20px">Flashcard confidence is self-reported and contributes to your review schedule. It is not a test score.</p></div>`;}
function progress(){const attempts=Object.values(S.stats).reduce((n,v)=>n+v.seen,0),correct=Object.values(S.stats).reduce((n,v)=>n+v.correct,0),tests=S.history.filter(h=>h.mock),recent=tests.slice(-5),avg=recent.length?Math.round(recent.reduce((n,h)=>n+h.score/40*100,0)/recent.length):null;const badges=[['🌱','First mile',S.lessons.length>0,'Read your first lesson'],['🧭','Explorer',S.lessons.length===Q.length,'Read all study lessons'],['🏁','Test trailblazer',tests.some(h=>h.score>=32),'Pass a mock test'],['☀','Steady traveler',streak()>=3,'Study 3 days in a row']];return heading('LOOK HOW FAR YOU’VE COME','Progress, one good habit at a time.','Your learning stays in this browser. Export a backup to take it with you.')+`<div class="stats">${stat('✦','lavender',S.xp,'EXPERIENCE POINTS')}${stat('✓','mint',attempts?Math.round(correct/attempts*100)+'%':'—','PRACTICE + RECALL ACCURACY')}${stat('▣','peach',avg===null?'—':avg+'%','LAST 5 MOCKS · AVERAGE')}${stat('☀','yellow',Object.keys(S.activity).length,'ACTIVE STUDY DAYS')}</div><div class="card"><h2>Your next best step</h2><p>${!attempts?'Start with a study route, then try a ten-question practice session.':wrongIds().length?`Revisit your ${wrongIds().length} most recently missed questions, then test yourself again.`:S.lessons.length<Q.length?'Keep exploring the course to fill in the topics you have not read yet.':'Try another mock test and read the full guide to keep context fresh.'}</p><button class="btn" data-go="${wrongIds().length?'review':'course'}">${wrongIds().length?'Visit your review queue':'Explore study routes'} →</button><div class="callout">Accuracy includes quiz answers and self-rated flashcards. “Two correct in a row” is a practice milestone, not proof of test readiness.</div></div><div class="section-heading"><h2>Little milestones, big momentum</h2></div><div class="badge-row">${badges.map(([icon,t,ok,d])=>`<div class="badge ${ok?'':'locked'}"><span>${icon}</span><strong>${t}</strong><small>${ok?'Unlocked · ':''}${d}</small></div>`).join('')}</div><div class="section-heading"><h2>Your topic map</h2></div><div class="topic-progress">${M.map(m=>{const qs=Q.filter(q=>q.module===m.id),seen=qs.filter(q=>S.stats[q.id]).length,master=qs.filter(q=>S.stats[q.id]?.run>=2).length;return `<div class="card"><strong>${m.icon} ${m.title}</strong><div class="progress-track"><span style="width:${master/qs.length*100}%"></span></div><p class="small" style="margin:10px 0 0">${completed(m)}/${qs.length} lessons read · ${seen} explored · ${master} with two correct in a row</p></div>`;}).join('')}</div><div class="section-heading"><h2>Your recent sessions</h2><button class="text-button" data-action="export">Export progress ↗</button></div><section class="card">${S.history.length?S.history.slice(-20).reverse().map(h=>`<div class="setting"><div><strong>${esc(h.title)}</strong><p>${new Date(h.date).toLocaleString()}${h.mock?` · ${h.score>=32?'Passed':'Keep practicing'}`:''}</p></div><strong>${h.score}/${h.total}</strong></div>`).join(''):'<p>Your completed sessions will appear here.</p>'}</section>`;}
function guide(){return heading('THE SOURCE OF TRUTH','The guide, right beside you.','The official PDF is included in this folder, so it’s always available offline.')+`<section class="card"><div class="actions" style="margin-top:0"><a class="btn" href="assets/washington-driver-guide.pdf" target="_blank" rel="noopener">Open the complete guide ↗</a><a class="btn secondary" href="${C.source}" target="_blank" rel="noopener">Check official source ↗</a></div><p class="small" style="margin-top:17px">Edition ${C.edition} · 191 PDF pages · downloaded November 9, 2026. Page links use PDF viewer page numbers. If your browser ignores a page link, type that page number in its PDF viewer.</p><label for="guide-search" class="eyebrow">FIND IT IN THE GUIDE</label><input id="guide-search" type="search" placeholder="Try “school bus”, “parking”, or “headlights”…" autocomplete="off"><div id="search-results" aria-live="polite"><p class="small" style="margin-top:15px">Search the offline text, or choose a chapter below. The original PDF is authoritative; extracted search text can lose visual formatting.</p></div></section><div class="section-heading"><h2>Go straight to a chapter</h2></div><div class="grid">${[['1','Licenses',18,'Permits, exams, and your responsibilities.'],['2','Vehicles',40,'Know your vehicle and keep it ready.'],['3','Drivers',67,'Attention, decisions, and impairment.'],['4','Roads',92,'Signs, sharing, intersections, and parking.'],['5','Risks',153,'Speed, conditions, and emergencies.']].map(([n,t,p,d])=>`<a class="card" href="assets/washington-driver-guide.pdf#page=${p}" target="_blank" rel="noopener" style="text-decoration:none"><div class="eyebrow">CHAPTER ${n}</div><h3>${t} ↗</h3><p class="small">${d}</p></a>`).join('')}</div><div class="section-heading"><h2>Clear sources. Clear expectations.</h2></div><section class="card"><p>Evergreen Drive is an independent study companion. Lesson summaries, questions, correct answers, and explanations are based on the linked Washington Driver Guide. Each item links to the supporting PDF page. It is not affiliated with or endorsed by Washington DOL.</p><p>The mock-test length and passing score were checked against the <a href="https://dol.wa.gov/driver-licenses-and-permits/driver-training-and-testing/do-i-need-take-test" target="_blank" rel="noopener">official DOL testing page</a>: 40 multiple-choice questions, with 32 correct required to pass. Our questions, topic allocation, interface, XP, and review schedule are original learning features.</p><p class="small">The guide contains nuance and illustrations beyond these focused lessons. Read it in full as part of your preparation. This app reflects the downloaded edition; it does not silently update laws or content.</p></section>`;}
function settings(){return heading('MAKE YOURSELF AT HOME','A quieter ride. Or a little celebration.','Your app, your pace, your progress.')+`<section class="card"><div class="setting"><div><strong>Sound effects</strong><p>Gentle tones for answers and milestones. No downloaded audio needed.</p></div><input type="checkbox" id="sound-setting" aria-label="Sound effects" ${S.sound?'checked':''}></div><div class="setting"><div><strong>Reduce motion</strong><p>Keep transitions and celebrations still. System preferences are also respected.</p></div><input type="checkbox" id="motion-setting" aria-label="Reduce motion" ${S.motion?'checked':''}></div><div class="setting"><div><strong>Export your progress</strong><p>Save a JSON backup before moving folders, switching browsers, or clearing browser data.</p></div><button class="btn secondary" data-action="export">Export backup</button></div><div class="setting"><div><strong>Import a backup</strong><p>Restore a previous backup. You will review it before it replaces local progress.</p></div><button class="btn secondary" data-action="import">Import backup</button></div><div class="setting"><div><strong>A fresh start</strong><p>Reset this browser’s lessons, scores, saved questions, and preferences.</p></div><button class="btn secondary" data-action="reset">Reset progress</button></div></section><div class="callout">${storageOK?'Local storage is available.':'Local storage is unavailable; export your progress before closing.'} Progress is saved to this browser, not written into the app folder. Private browsing or moving the folder can change persistence. No accounts, analytics, or network requests are used by the app. External source links open only when you choose them.</div><section class="card"><h2>How to share</h2><p>Send the entire Evergreen-Drive folder or its ZIP. The recipient extracts the ZIP, then double-clicks <strong>index.html</strong>. Keep the assets folder and JavaScript/CSS files beside it.</p><p class="small">Use a current desktop browser such as Chrome, Edge, Firefox, or Safari. Your study data is not included when you share the app folder. Share an exported progress file separately only if you intend to.</p></section>`;}
function render(){const path=location.hash.slice(1).split('/'),view=path[0]||'home';const fn={home,course:()=>course(path[1]),practice,mock,session,review,flash:flashView,signs:signAtlas,progress,source:guide,settings}[view]||home;document.getElementById('main').innerHTML=fn();document.getElementById('page-label').textContent=navs.find(n=>n[0]===view)?.[2]||({session:'Your session',flash:'Flashcards',settings:'Preferences',signs:'Sign atlas'}[view]||'Dashboard');chrome();window.scrollTo(0,0);}
let imported=null;
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();document.getElementById('main').focus();return;}const b=e.target.closest('button,[data-go]');if(!b)return;if(b.dataset.go){go(b.dataset.go);return;}const action=b.dataset.action,id=b.dataset.id,a=S.session;switch(action){
case 'visual-practice':startSession(shuffle(Q.filter(q=>q.visualQuestion).map(q=>q.id)),'Visual signs & road markings');break;
case 'visual-flash':startFlash(shuffle(Q.filter(q=>q.visualQuestion).map(q=>q.id)));break;
case 'start-mock':startSession(mockIds(+id),`Mock test ${String(id).padStart(2,'0')}`,'mock',+id);break;
case 'practice-custom':{const t=document.getElementById('practice-topic').value,n=+document.getElementById('practice-count').value;startSession(shuffle(Q.filter(q=>t==='all'||q.module===t).map(q=>q.id)).slice(0,n),t==='all'?'Mixed practice':mod(t).title);break;}
case 'practice-topic':startSession(shuffle(Q.filter(q=>q.module===id).map(q=>q.id)),mod(id).title);break;
case 'daily':startSession(shuffle(Q.map(q=>q.id),seeded(Number(dateKey().replaceAll('-','')))).slice(0,5),'The daily five');break;
case 'read':if(!S.lessons.includes(id)){S.lessons.push(id);activity(5);save();sound('correct');toast('Lesson complete. +5 XP');}go(b.dataset.next);break;
case 'bookmark':S.bookmarks=S.bookmarks.includes(id)?S.bookmarks.filter(v=>v!==id):[...S.bookmarks,id];save();b.textContent=S.bookmarks.includes(id)?'★ Saved':'☆ Save for later';toast(S.bookmarks.includes(id)?'Saved for another look.':'Removed from saved questions.');break;
case 'answer':if(!a||a.finished)return;{const qid=a.ids[a.index],choice=+b.dataset.choice;if(a.mode==='practice'&&a.answers[qid]!==undefined)return;a.answers[qid]=choice;if(a.mode==='practice'){record(qid,choice===byId[qid].answer);a.recorded.push(qid);sound(choice===byId[qid].answer?'correct':'wrong');}else sound();save();render();}break;
case 'next':if(a&&a.index<a.ids.length-1){a.index++;save();render();}break;
case 'previous':if(a&&a.index>0){a.index--;save();render();}break;
case 'jump':if(a){a.index=+b.dataset.index;save();render();}break;
case 'flag':if(a){const qid=a.ids[a.index];a.flags=a.flags.includes(qid)?a.flags.filter(v=>v!==qid):[...a.flags,qid];save();render();}break;
case 'submit':submit();break;
case 'finish':finish();break;
case 'close':closeModal();break;
case 'resume-modal':closeModal();go('session');break;
case 'replace-session':closeModal();pendingStart?.();pendingStart=null;break;
case 'retry-missed':{const ids=a.ids.filter(id=>a.answers[id]!==byId[id].answer);if(ids.length)startSession(shuffle(ids),'Missed question practice');else toast('No missed questions — nicely done!');break;}
case 'review-wrong':startSession(shuffle(wrongIds()),'Your missed questions');break;
case 'review-saved':startSession(shuffle(S.bookmarks),'Your saved questions');break;
case 'flash':startFlash();break;
case 'flash-due':startFlash(shuffle(dueIds()));break;
case 'atlas-page':go('signs/'+b.dataset.page);break;
case 'flip':if(flash){flash.revealed=!flash.revealed;sound();render();}break;
case 'flash-rate':if(flash?.revealed){const ok=b.dataset.known==='yes';record(flash.ids[flash.index],ok);flash.known+=ok?1:0;flash.index++;flash.revealed=false;save();sound(ok?'correct':'tap');render();}break;
case 'export':{const blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`evergreen-progress-${dateKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress backup prepared.');break;}
case 'import':document.getElementById('import-file').click();break;
case 'confirm-import':if(imported){S=imported;imported=null;save();closeModal();render();toast('Your progress is restored.');}break;
case 'reset':modal('<h2>Start fresh?</h2><p>This removes all progress saved by this app in this browser. Export a backup first if you might want it later.</p><div class="actions"><button class="btn danger" data-action="confirm-reset">Reset all progress</button><button class="btn secondary" data-action="close">Keep my progress</button></div>');break;
case 'confirm-reset':S=fresh();flash=null;save();closeModal();render();toast('A fresh road ahead.');break;
}});
document.getElementById('sound').addEventListener('click',()=>{S.sound=!S.sound;save();sound('correct');toast(S.sound?'Sound effects on.':'Sound effects off.');});
document.addEventListener('change',async e=>{if(e.target.id==='sound-setting'){S.sound=e.target.checked;save();sound('correct');}if(e.target.id==='motion-setting'){S.motion=e.target.checked;save();}if(e.target.id==='missed-only')document.getElementById('result-list').innerHTML=resultItems(e.target.checked);if(e.target.id==='import-file'){const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>3e6)throw Error('Too large');imported=validateState(JSON.parse(await f.text()));modal(`<h2>Restore this progress?</h2><p>This backup contains ${imported.lessons.length} read lesson${imported.lessons.length===1?'':'s'} and ${imported.history.length} completed session${imported.history.length===1?'':'s'}. It will replace the progress currently saved in this browser.</p><div class="actions"><button class="btn" data-action="confirm-import">Restore backup</button><button class="btn secondary" data-action="close">Cancel</button></div>`);}catch(err){toast('That file is not a valid Evergreen Drive backup. Nothing was changed.');}}});
let searchTimer;
document.addEventListener('input',e=>{if(e.target.id!=='guide-search')return;const term=e.target.value.trim();clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const box=document.getElementById('search-results');if(!box)return;if(term.length<2){box.innerHTML='<p class="small" style="margin-top:12px">Type at least two characters to search the guide.</p>';return;}const found=C.pages.filter(p=>p.text.toLowerCase().includes(term.toLowerCase()));box.innerHTML=`<p class="small" style="margin-top:12px">${found.length} matching pages${found.length>30?' · showing the first 30':''}</p>`+found.slice(0,30).map(p=>{const i=p.text.toLowerCase().indexOf(term.toLowerCase()),start=Math.max(0,i-130),end=Math.min(p.text.length,i+term.length+250),snippet=p.text.slice(start,end);return `<details class="source-result"><summary>PDF page ${p.page} · ${esc(p.text.slice(0,75).replaceAll('\n',' '))}</summary><p>${esc(p.text)}</p><a class="source-link" href="assets/washington-driver-guide.pdf#page=${p.page}" target="_blank" rel="noopener">Open original page ↗</a></details><p class="small">…${esc(snippet)}…</p>`;}).join('');},180);});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.getElementById('modal').open)return;if(location.hash==='#session'&&S.session&&!S.session.finished){const a=S.session;if(/^[1-4]$/.test(e.key)){const buttons=document.querySelectorAll('.answer');buttons[+e.key-1]?.click();e.preventDefault();}if(e.key==='Enter'&&e.target.tagName!=='BUTTON'&&a.answers[a.ids[a.index]]!==undefined){document.querySelector('[data-action="next"], [data-action="submit"]')?.click();e.preventDefault();}}if(location.hash==='#flash'&&e.code==='Space'&&e.target.tagName!=='BUTTON'){document.querySelector('[data-action="flip"]')?.click();e.preventDefault();}});
window.addEventListener('hashchange',()=>{render();document.getElementById('main').focus({preventScroll:true});});
setInterval(()=>{const el=document.getElementById('elapsed');if(el&&S.session&&!S.session.finished)el.textContent=elapsed(S.session);},1000);
render();

function signAtlas(){if(!location.hash.split('/')[1])return visualGallery();const labels=['Red signals','Yellow signals','Green signals','Sign colors & ramp meters','Stop, yield & speed','Directions & speed warnings','Restrictions & turn lanes','Roundabouts & work zones','Services & destinations','Common warning signs','More warning signs'];const p=Math.max(110,Math.min(120,Number(location.hash.split('/')[1])||110));return heading('LOOK CLOSELY. RECOGNIZE QUICKLY.','Your illustrated sign atlas.','Original illustrations from the official guide. Choose a page to explore.')+`<div class="actions"><button class="btn secondary" data-go="signs">← Illustrated cards</button></div>`+`<div class="study-layout"><aside class="study-tabs" aria-label="Sign atlas pages">${labels.map((t,i)=>`<button class="${p===i+110?'selected':''}" data-action="atlas-page" data-page="${i+110}">${t}</button>`).join('')}</aside><section class="card"><div class="quiz-top"><h2>${labels[p-110]}</h2><a class="source-link" href="assets/washington-driver-guide.pdf#page=${p}" target="_blank" rel="noopener">Original PDF page ${p} ↗</a></div><img class="atlas-page" src="assets/signs/page-${p}.png" alt="Official Washington Driver Guide page ${p}: ${labels[p-110]}. Open the original PDF for accessible document text."><div class="actions between"><button class="btn secondary" data-action="atlas-page" data-page="${p-1}" ${p===110?'disabled':''}>← Previous</button><button class="btn" data-action="practice-topic" data-id="signals">Practice these ideas →</button><button class="btn secondary" data-action="atlas-page" data-page="${p+1}" ${p===120?'disabled':''}>Next →</button></div></section></div>`;}

function visualGallery(){const qs=Q.filter(q=>q.id.startsWith('v'));return heading('YOUR VISUAL ROAD DICTIONARY','Recognize the road at a glance.','Learn the actual signs and markings shown in the official Washington guide.')+`<div class="visual-entry card"><div><h2>Look first. Then test yourself.</h2><p>Study the meaning below each image, or hide the answers in visual practice.</p></div><div class="actions"><button class="btn" data-action="visual-practice">Visual practice →</button><button class="btn secondary" data-action="visual-flash">Visual flashcards</button><button class="btn secondary" data-go="signs/110">Full guide pages ↗</button></div></div><div class="grid visual-gallery">${qs.map(q=>`<article class="card"><div class="visual-illustration">${scene(q)}</div><h3>${esc(q.choices[q.answer])}</h3><p class="small">${esc(q.explanation)}</p>${source(q)}<div class="actions"><button class="text-button" data-go="course/${q.module}/${Q.filter(v=>v.module===q.module).findIndex(v=>v.id===q.id)}">Study this illustration →</button></div></article>`).join('')}</div>`;}
